<?php
declare(strict_types=1);
use App\Http\Controllers\Personnel\{PersonnelAccountController,PersonnelController,PersonnelExportController,PersonnelImportController,PersonnelStatusController,PersonnelTemplateController}; use Illuminate\Support\Facades\Route;
Route::middleware(['auth','active','force-password-change'])->prefix('personnel')->name('personnel.')->group(function():void{
 Route::get('/import',[PersonnelImportController::class,'form'])->middleware('permission:personnel.import')->name('import.form'); Route::post('/import/preview',[PersonnelImportController::class,'preview'])->middleware('permission:personnel.import')->name('import.preview'); Route::post('/import/confirm',[PersonnelImportController::class,'confirm'])->middleware('permission:personnel.import')->name('import.confirm'); Route::get('/import/{batch}',[PersonnelImportController::class,'result'])->middleware('permission:personnel.import')->name('import.result'); Route::get('/import/{batch}/errors',[PersonnelImportController::class,'errors'])->middleware('permission:personnel.import')->name('import.errors');
 Route::get('/template',PersonnelTemplateController::class)->middleware('permission:personnel.export')->name('template'); Route::get('/export',PersonnelExportController::class)->middleware('permission:personnel.export')->name('export'); Route::get('/create',[PersonnelController::class,'create'])->middleware('permission:personnel.create')->name('create'); Route::post('/',[PersonnelController::class,'store'])->middleware('permission:personnel.create')->name('store'); Route::get('/',[PersonnelController::class,'index'])->middleware('permission:personnel.view')->name('index');
 Route::get('/{personnel}/edit',[PersonnelController::class,'edit'])->middleware('permission:personnel.update')->name('edit'); Route::put('/{personnel}',[PersonnelController::class,'update'])->middleware('permission:personnel.update')->name('update'); Route::patch('/{personnel}/activate',[PersonnelStatusController::class,'activate'])->middleware('permission:personnel.activate')->name('activate'); Route::patch('/{personnel}/deactivate',[PersonnelStatusController::class,'deactivate'])->middleware('permission:personnel.activate')->name('deactivate'); Route::get('/{personnel}/account',[PersonnelAccountController::class,'edit'])->middleware('permission:personnel.manage-account')->name('account.edit'); Route::patch('/{personnel}/account',[PersonnelAccountController::class,'update'])->middleware('permission:personnel.manage-account')->name('account.update'); Route::delete('/{personnel}/account',[PersonnelAccountController::class,'destroy'])->middleware('permission:personnel.manage-account')->name('account.destroy'); Route::get('/{personnel}',[PersonnelController::class,'show'])->middleware('permission:personnel.view')->name('show');
});
